os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
common=["-Xbatch","-XX:+UseSerialGC","-Xms1g","-Xmx1g","-XX:ActiveProcessorCount=2"]
modes=("base","on","control","policy","loop","base64","api","copy","native1","off","policyOff","copyOff")
for mode in modes:
    java=(base if mode=="base" else head)/"bin/java"
    variant={"policyOff":"policy","copyOff":"copy"}.get(mode,mode)
    extra=["--patch-module=java.base="+str(patches[variant])] if variant in patches else []
    if mode in ("off","policyOff","copyOff"):extra.append("-XX:-UseSIMDUTFIntrinsics")
    if mode=="native1":extra.append("-XX:SIMDUTFMinLength=1")
    string=[("string","c1","latin1Decode","16,128,4096",3),("string-c2","c2","latin1Decode","16,128,4096",3),("other","c1","utf8Decode|supplementaryDecode","31,4096",4)]
    encoding=[("base64","c1","base64Encode|base64Decode","3,31,63,255,258,4096",12),("base64-c2","c2","base64Encode|base64Decode","63,4096",4)]
    copying=[("copy","c1","utf16GetChars|utf16ToChars","1,31,4096",6),("copy-c2","c2","utf16GetChars|utf16ToChars","1,31,4096",6)]
    if mode in ("base","on","control"):cases=string+encoding+copying
    elif mode in ("policy","loop"):cases=string
    elif mode=="base64":cases=encoding
    elif mode in ("api","copy"):cases=copying
    elif mode=="native1":cases=[encoding[0]]
    elif mode=="off":cases=[string[0],encoding[0],copying[0]]
    elif mode=="policyOff":cases=[string[0]]
    else:cases=[copying[0]]
    if mode in ("base","on","base64","native1"):
        cases.append(("base64-interp","interp","base64Encode","3,31,63,4096",4))
    for study,tier,methods,sizes,expected in cases:
        flags=["-Xint"] if tier=="interp" else ["-XX:TieredStopAtLevel=1"] if tier=="c1" else ["-XX:-TieredCompilation","-XX:CompileThreshold=100"]
        result=out/(mode+"-"+study+".json")
        cmd=[str(java),"-cp",cp,"org.openjdk.jmh.Main","org.openjdk.bench.java.lang.SimdUTF.("+methods+")$","-p","size="+sizes,"-f","2","-wi","3","-i","3","-w","200ms","-r","200ms","-t","1","-prof","gc","-jvm",str(java),"-jvmArgs"," ".join([*common,*flags,*extra]),"-rf","json","-rff",str(result)]
        print("FALLBACK_START",mode,study,flush=True)
